const stageColors=[['#67b9c5','#cbe7c3','#268f9d','#ac7350','#76b663'],['#eab971','#fff0bc','#51a7ad','#bb8752','#d8c48d'],['#b86b76','#f7c7a4','#986589','#aa6663','#d4a476'],['#9ec592','#dfecc2','#409e91','#927856','#89b66c'],['#7aa8b0','#c4e0d4','#3f879b','#817a70','#91b6a4'],['#253454','#7c81ad','#415c87','#676281','#a2a3bf'],['#98b9d9','#e5f6ff','#508dad','#a1a6bf','#dceaf2'],['#7a485c','#efa57a','#8b5969','#8a5054','#cc996d'],['#8897cf','#e6d6ee','#717aab','#8b729a','#c4b3d9'],['#dfa971','#f9e3a7','#80a8ae','#ba8b58','#e0c48d'],['#3c657c','#96b5be','#3c7184','#74797b','#91aaa3'],['#211e43','#705b9c','#474674','#66537b','#a394c8']];
